local HatStretcherMaker = {}
local PRODUCTS = {
    iron_hatstretcher = { name = "Železni naprtevalec za klobuke", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni naprtevalec za klobuke za klobucarje." },
    bronze_hatstretcher = { name = "Bronast naprtevalec za klobuke", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast naprtevalec za klobuke za klobucarje." },
    silver_hatstretcher = { name = "Srebrn naprtevalec za klobuke", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn naprtevalec za klobuke za klobucarje." },
    gilded_hatstretcher = { name = "Pozlačen naprtevalec za klobuke", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen naprtevalec za klobuke za klobucarje." },
    jewel_set_hatstretcher = { name = "Draguljast naprtevalec za klobuke", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast naprtevalec za klobuke za klobucarje." },
    royal_sovereign_hatstretcher = { name = "Kraljevski suveren naprtevalec za klobuke", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren naprtevalec za klobuke z biseri za krono." },
}
local BUILDINGS = {
    hatstretcher_workshop = { name = "Hatstretcher delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    hatstretcher_house = { name = "Hatstretcher hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hatstretcher_atelier = { name = "Mojstrski hatstretcher atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_hatstretcher_palace = { name = "Suverena hatstretcher palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HatStretcherMaker.ironStock = 12; HatStretcherMaker.bronzeStock = 10; HatStretcherMaker.woodStock = 18; HatStretcherMaker.leatherStock = 10; HatStretcherMaker.silverStock = 8; HatStretcherMaker.goldStock = 6; HatStretcherMaker.jewelStock = 4; HatStretcherMaker.pearlStock = 4
HatStretcherMaker.productStock = {}; HatStretcherMaker.buildings = {}; HatStretcherMaker.maker = nil; HatStretcherMaker.activeMaking = {}; HatStretcherMaker.totalProducts = 0; HatStretcherMaker.dayTimer = 0
function HatStretcherMaker.init() HatStretcherMaker.ironStock=12; HatStretcherMaker.bronzeStock=10; HatStretcherMaker.woodStock=18; HatStretcherMaker.leatherStock=10; HatStretcherMaker.silverStock=8; HatStretcherMaker.goldStock=6; HatStretcherMaker.jewelStock=4; HatStretcherMaker.pearlStock=4; HatStretcherMaker.productStock={}; HatStretcherMaker.buildings={}; HatStretcherMaker.maker=nil; HatStretcherMaker.activeMaking={}; HatStretcherMaker.totalProducts=0; HatStretcherMaker.dayTimer=0; print("[HatStretcherMaker] Royal Hat Stretcher Maker System initialized (6 products, 4 buildings)") end
function HatStretcherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HatStretcherMaker.maker={name=n or ("Naprtevalc "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Naprtevalc najet: %s (spretnost: %d)",HatStretcherMaker.maker.name,s),"success") end; return true end
function HatStretcherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HatStretcherMaker.build(id) local ok,e=HatStretcherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HatStretcherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HatStretcherMaker.getQualityBonus() local b=0; for _,bd in ipairs(HatStretcherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HatStretcherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HatStretcherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HatStretcherMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HatStretcherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HatStretcherMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HatStretcherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HatStretcherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HatStretcherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HatStretcherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HatStretcherMaker.buildings==0 then return false,"Potrebna naprtevalna delavnica" end; if not HatStretcherMaker.maker then return false,"Potreben naprtevalec" end; return true end
function HatStretcherMaker.make(pt,qty) qty=qty or 1; local ok,e=HatStretcherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HatStretcherMaker.ironStock=HatStretcherMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HatStretcherMaker.bronzeStock=HatStretcherMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HatStretcherMaker.woodStock=HatStretcherMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HatStretcherMaker.leatherStock=HatStretcherMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HatStretcherMaker.silverStock=HatStretcherMaker.silverStock-d.silverCost*qty end; if d.goldCost then HatStretcherMaker.goldStock=HatStretcherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HatStretcherMaker.jewelStock=HatStretcherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HatStretcherMaker.pearlStock=HatStretcherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HatStretcherMaker.maker then t=math.max(1,t-math.floor(HatStretcherMaker.maker.skill/13)) end; table.insert(HatStretcherMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HatStretcherMaker.completeMaking(m) local q=1.0+(HatStretcherMaker.getQualityBonus()/100); if HatStretcherMaker.maker then q=q+(HatStretcherMaker.maker.skill/140) end; q=math.min(2.5,q); HatStretcherMaker.productStock[m.productType]=(HatStretcherMaker.productStock[m.productType] or 0)+m.quantity; HatStretcherMaker.totalProducts=HatStretcherMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HatStretcherMaker.maker then HatStretcherMaker.maker.itemsMade=HatStretcherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HatStretcherMaker.maker.skill=math.min(100,HatStretcherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Naprtevalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function HatStretcherMaker.update(dt) if not _G.state then return end; HatStretcherMaker.dayTimer=HatStretcherMaker.dayTimer+dt; if HatStretcherMaker.dayTimer>=30 then HatStretcherMaker.dayTimer=0; for i=#HatStretcherMaker.activeMaking,1,-1 do local m=HatStretcherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HatStretcherMaker.completeMaking(m); table.remove(HatStretcherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HatStretcherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HatStretcherMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HatStretcherMaker.getStats() return {ironStock=HatStretcherMaker.ironStock,bronzeStock=HatStretcherMaker.bronzeStock,woodStock=HatStretcherMaker.woodStock,leatherStock=HatStretcherMaker.leatherStock,silverStock=HatStretcherMaker.silverStock,goldStock=HatStretcherMaker.goldStock,jewelStock=HatStretcherMaker.jewelStock,pearlStock=HatStretcherMaker.pearlStock,productStock=HatStretcherMaker.productStock,numBuildings=#HatStretcherMaker.buildings,hasMaker=HatStretcherMaker.maker~=nil,makerName=HatStretcherMaker.maker and HatStretcherMaker.maker.name or "—",makerSkill=HatStretcherMaker.maker and HatStretcherMaker.maker.skill or 0,activeMaking=#HatStretcherMaker.activeMaking,totalProducts=HatStretcherMaker.totalProducts} end
return HatStretcherMaker
